// Inline Leaflet into the app bundle, so the maps never fetch it at runtime.
//
//   node scripts/vendor-leaflet.mjs     (runs as `postinstall`; no arguments)
//
// Reads dist/leaflet.js and dist/leaflet.css from the installed `leaflet`
// package and writes them as two string constants to
// src/vendor/leaflet.generated.ts, which leafletWebView.ts puts inline in each
// map document. Both maps used to load Leaflet from unpkg.com: a map was blank
// whenever unpkg was down or blocked, and unpkg saw every map user's IP address
// (docs/todo.md §8.2, §9.1).
//
// The generated file is gitignored and rebuilt on every `npm install` / `npm ci`
// — build-apk.bat, scripts/build.sh, setup.bat and CI all run one — so it always
// matches node_modules. If it is missing, Metro fails to resolve the import and
// the build stops: no APK can ship a map without Leaflet.
//
// The SHA-512 pins below are the Subresource Integrity hashes the unpkg <script>
// and <link> tags carried, and they still do that job: what gets inlined is
// byte-for-byte the release that was reviewed. Bumping Leaflet means changing
// the exact version in package.json AND here, and recomputing both hashes:
//   openssl dgst -sha512 -binary node_modules/leaflet/dist/leaflet.js | openssl base64 -A

import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const LEAFLET_VERSION = "1.9.4";
const PINNED_SHA512 = {
  "leaflet.js":
    "BwHfrr4c9kmRkLw6iXFdzcdWV/PGkVgiIyIWLLlTSXzWQzxuSg4DiQUCpauz/EWjgk5TYQqX/kvn9pG1NpYfqg==",
  "leaflet.css":
    "Zcn6bjR/8RZbLEpLIeOwNtzREBAJnUKESxces60Mpoj+2okopSAcSUIUOseddDm0cxnGQzxIR7vJgsLZbdLE3w==",
};

const here = dirname(fileURLToPath(import.meta.url));
const frontend = resolve(here, "..");
const leafletDir = join(frontend, "node_modules", "leaflet");
const outFile = join(frontend, "src", "vendor", "leaflet.generated.ts");

function fail(message) {
  console.error(`vendor-leaflet: ${message}`);
  process.exit(1);
}

// A caret range would let `npm install` move to a release whose hashes nobody
// has checked, and this script would then refuse to run — fail on the cause.
const declared = JSON.parse(readFileSync(join(frontend, "package.json"), "utf8"))
  .dependencies?.leaflet;
if (declared !== LEAFLET_VERSION) {
  fail(`package.json must pin "leaflet": "${LEAFLET_VERSION}" exactly (found ${JSON.stringify(declared)}).`);
}
if (!existsSync(leafletDir)) fail("node_modules/leaflet is missing — run npm install first.");
const installed = JSON.parse(readFileSync(join(leafletDir, "package.json"), "utf8")).version;
if (installed !== LEAFLET_VERSION) {
  fail(`installed leaflet is ${installed}, expected ${LEAFLET_VERSION}.`);
}

function readPinned(name) {
  const bytes = readFileSync(join(leafletDir, "dist", name));
  const digest = createHash("sha512").update(bytes).digest("base64");
  if (digest !== PINNED_SHA512[name]) {
    fail(`dist/${name} does not match its pinned SHA-512 (got ${digest}). `
      + "Either the package was tampered with or the version changed without the pin.");
  }
  return bytes.toString("utf8");
}

// The source-map comment would point the WebView's devtools at a file that is
// not there; nothing else in the minified build is touched.
const js = readPinned("leaflet.js").replace(/\n\/\/# sourceMappingURL=\S+\s*$/, "\n");
const css = readPinned("leaflet.css");

// Inside an inline <script>/<style>, these sequences end the element early (or,
// for `<!--` and `<script`, change how the HTML parser reads what follows).
// Leaflet 1.9.4 contains none; a future version that did would break the page
// in ways that are hard to see, so refuse rather than escape blindly.
if (/<\/script|<!--|<script/i.test(js)) fail("leaflet.js contains a sequence that cannot be inlined in <script>.");
if (/<\/style/i.test(css)) fail("leaflet.css contains a sequence that cannot be inlined in <style>.");

const output = `// GENERATED by scripts/vendor-leaflet.mjs from leaflet@${LEAFLET_VERSION}
// (node_modules/leaflet/dist, SHA-512 checked). Do not edit and do not commit:
// it is rebuilt by every \`npm install\`.
//
// Leaflet is BSD-2-Clause, (c) 2010-2023 Vladimir Agafonkin, (c) 2010-2011
// CloudMade; its notice is kept at the top of LEAFLET_JS.

export const LEAFLET_VERSION = ${JSON.stringify(LEAFLET_VERSION)};

export const LEAFLET_JS = ${JSON.stringify(js)};

export const LEAFLET_CSS = ${JSON.stringify(css)};
`;

mkdirSync(dirname(outFile), { recursive: true });
// Rewrite only on change, so an unrelated `npm install` does not invalidate
// Metro's cache for every module that imports this one.
if (!existsSync(outFile) || readFileSync(outFile, "utf8") !== output) {
  writeFileSync(outFile, output);
  console.log(`vendor-leaflet: wrote src/vendor/leaflet.generated.ts (leaflet ${LEAFLET_VERSION})`);
}
